'use strict';
/* Materiais de Apoio — parte E: Ortografia e Sintaxe (norma do português europeu, Acordo Ortográfico de 1990,
   terminologia do Dicionário Terminológico usado nas escolas portuguesas). Mesmo formato das partes anteriores.
   Os exemplos sem autor são frases criadas para ilustrar a regra. */

/* ============ ORTOGRAFIA ============ */
SUPPORT.push({ key:'ortografia', name:'Ortografia', kicker:'Ortografia',
  intro:'Como se escrevem as palavras: acentos, hífen, maiúsculas, consoantes que se leem ou não, e as palavras parecidas que mais se confundem. Segue-se o Acordo Ortográfico de 1990, tal como se aplica em Portugal (Vocabulário Ortográfico do Português e prática das editoras), e assinalam-se as diferenças em relação ao Brasil. Para as grafias anteriores, veja a secção «Escrita Antiga».',
  groups:[

  { name:'Acentuação', items:[
    { n:'Regras de acentuação', a:'Agudas, graves e esdrúxulas · acento agudo, grave, circunflexo e til',
      d:'Em português, a sílaba tónica é marcada por acento gráfico só quando a regra geral não chega para a indicar. As palavras dividem-se pela posição da sílaba tónica: agudas (última), graves (penúltima) e esdrúxulas (antepenúltima).',
      u:'Esdrúxulas: acentuam-se sempre («pássaro», «lâmpada», «público»). Graves: são a regra, e só se acentuam quando terminam em -l, -n, -r, -x, -ps, -ão(s), -ã(s), -um/-uns, -i(s), -us, ou ditongo oral («fácil», «hífen», «açúcar», «tórax», «bíceps», «órfão», «álbum», «táxi», «vírus», «história»). Agudas: acentuam-se quando terminam em -a(s), -e(s), -o(s), -em/-ens com mais de uma sílaba («sofá», «café», «avó», «também», «parabéns»). O acento agudo marca vogal aberta («avó»), o circunflexo vogal fechada («avô»), o grave só a contração da preposição «a» («à», «àquele»), o til a nasalidade («mãe», «coração»).',
      c:'Os monossílabos tónicos seguem a regra das agudas («pá», «pé», «pó», «mês») e os átonos nunca levam acento («me», «te», «se»). O i e o u tónicos em hiato acentuam-se («saída», «baú», «país»), exceto antes de «nh» («rainha») e quando formam sílaba com a consoante seguinte, que não seja s («ruim», «juiz», «Raul»; mas «juízes»). Com o Acordo de 1990, deixaram de se acentuar depois de ditongo nas palavras graves («feiúra» → «feiura»).',
      x:['Esdrúxulas: «árvore», «sílaba», «último».', 'Graves acentuadas: «amável», «pólen», «caráter», «lápis».', 'Agudas acentuadas: «está», «você», «armazém».', 'Abertura e fecho: «avó» / «avô»; «pôde» (passado) / «pode» (presente).'],
      s:['Acentos que o Acordo de 1990 mudou', 'Português de Portugal e do Brasil: ortografia', 'Confusões frequentes: à, há, a'] },
    { n:'Acentos que o Acordo de 1990 mudou', a:'Acento diferencial · lêem/leem · pára/para',
      d:'O Acordo de 1990 retirou vários acentos chamados diferenciais (que só serviam para distinguir palavras com a mesma grafia) e o circunflexo das formas verbais com «-eem».',
      u:'Perderam o acento: «pára» (verbo) → «para»; «pêlo» → «pelo»; «pólo» → «polo»; «pêra» → «pera»; «lêem», «vêem», «dêem», «crêem» → «leem», «veem», «deem», «creem»; «vôo» (Brasil) → «voo»; o acento agudo dos ditongos abertos ói e éi nas palavras graves («heróico» → «heroico», «jibóia» → «jiboia», «bóia» → «boia»), que se mantém nas agudas («herói», «papéis»). Mantêm-se: «pôr» (verbo) / «por» (preposição); «pôde» / «pode». Facultativos em Portugal: «dêmos»/«demos» (conjuntivo/pretérito), «fôrma»/«forma» (molde/feitio), e o acento nas formas do pretérito perfeito da 1.ª pessoa do plural, que em Portugal se usa para as distinguir do presente: «amámos» (passado) / «amamos» (agora).',
      c:'«Para» (verbo) e «para» (preposição) passaram a escrever-se igual: o contexto tem de bastar. Em Portugal, escreva «amámos», «cantámos», «chegámos» quando é passado — é a prática corrente e distingue o tempo.',
      x:['«O comboio para em Coimbra.» (antes: «pára»)', '«Eles leem o jornal todas as manhãs.» (antes: «lêem»)', '«Ontem chegámos tarde; hoje chegamos cedo.»'],
      s:['Regras de acentuação', 'Acordo Ortográfico de 1990'] }
  ]},

  { name:'Hífen e palavras compostas', items:[
    { n:'Hífen com prefixos', a:'auto-, anti-, co-, pré-, pós-, ex-, sub-, super-…',
      d:'Com o Acordo de 1990, o hífen depois de um prefixo depende sobretudo da letra com que o prefixo acaba e da letra com que a palavra seguinte começa.',
      u:'Com hífen: quando o prefixo acaba na mesma vogal com que começa a palavra («micro-ondas», «contra-ataque», «anti-inflamatório»); antes de «h» («anti-higiénico», «pré-história»), exceto com «co-», «re-», «des-» e «in-», que se juntam e perdem o h («coerdeiro», «reabilitar», «desumano», «inábil»); com os prefixos tónicos «pré-», «pós-», «pró-» («pré-escolar», «pós-guerra»); com «ex-» (anterior), «vice-», «sem-», «além-», «aquém-», «recém-» («ex-marido», «vice-reitor», «recém-nascido»); com «circum-» e «pan-» antes de vogal, «m», «n» e «h»; com «sub-» e «sob-» antes de «r» («sub-região») e com «sub-» antes de «b» e «h» («sub-base», «sub-humano»); com «hiper-», «inter-» e «super-» antes de «r» («hiper-realista», «inter-regional», «super-revista»). Sem hífen: quando as vogais são diferentes («autoestrada», «antiaéreo», «semiaberto»); antes de consoante («minissaia», «supermercado»); e, depois de um prefixo terminado em vogal, quando a palavra começa por «r» ou «s», que se dobram («antirreligioso», «contrassenso», «microssistema»). O prefixo «co-» junta-se em geral («coautor», «coocupante», «corresponsável»).',
      c:'Os prefixos átonos «pre-», «pro-», «re-» juntam-se sem hífen («prever», «procriar», «reeleger»). Muitas grafias com hífen anteriores a 2009 desapareceram: «auto-estrada», «anti-religioso», «co-autor», «semi-selvagem» (hoje «semisselvagem»).',
      x:['«micro-ondas», «contra-argumento», «arqui-inimigo»', '«autoestrada», «extraescolar», «infraestrutura»', '«antissocial», «ultrassom», «autorretrato»', '«ex-namorada», «pós-graduação», «sem-abrigo»'],
      s:['Hífen em compostos e locuções', 'Acordo Ortográfico de 1990'] },
    { n:'Hífen em compostos e locuções', a:'guarda-chuva · fim de semana · cor-de-rosa · dá-lo-ei',
      d:'As palavras compostas por justaposição (dois elementos que formam uma só ideia) levam hífen; as locuções com elemento de ligação (de, a, e…) perderam-no com o Acordo de 1990, com algumas exceções consagradas.',
      u:'Com hífen: compostos sem elemento de ligação («guarda-chuva», «arco-íris», «segunda-feira», «couve-flor», «azul-escuro»); espécies botânicas e zoológicas, mesmo com ligação («erva-doce», «bem-me-quer», «cobra-capelo», «andorinha-do-mar»); exceções consagradas («água-de-colónia», «arco-da-velha», «cor-de-rosa», «mais-que-perfeito», «pé-de-meia», «ao deus-dará», «à queima-roupa»). Sem hífen: locuções com elemento de ligação («fim de semana», «dia a dia», «cor de vinho», «pé de vento», «mão de obra», «hei de», «há de»). Pronomes: hífen na ênclise e na mesóclise («disse-lhe», «dá-lo-ei», «encontrar-nos-emos»).',
      c:'«Hei-de», «há-de», «fim-de-semana», «dia-a-dia», «pára-quedas» são grafias anteriores ao Acordo («hei de», «há de», «fim de semana», «dia a dia», «paraquedas»). «Bem-» liga-se com hífen à maioria das palavras («bem-vindo», «bem-estar»), mas há aglutinações («benfeitor», «benquisto»); «mal-» leva hífen antes de vogal, «h» e «l» («mal-estar», «mal-humorado», «mal-limpo»).',
      x:['«O guarda-chuva ficou no comboio.»', '«Passaram o fim de semana na praia.»', '«Hás de ver.» (e não «Hás-de ver»)', '«Dir-te-ei amanhã.»'],
      s:['Hífen com prefixos', 'Hífen, meia-risca e travessão', 'Colocação dos pronomes'] }
  ]},

  { name:'Letras e grafias', items:[
    { n:'Consoantes mudas', a:'acção → ação · óptimo → ótimo · facto e contacto mantêm-se',
      d:'Antes do Acordo de 1990, Portugal mantinha consoantes que não se pronunciam («c» e «p» antes de outra consoante) por razões etimológicas. O Acordo eliminou-as quando não se leem e manteve-as quando se leem.',
      u:'Caíram (não se pronunciam): «ação», «ator», «direção», «diretor», «exato», «ótimo», «adoção», «batismo», «Egito», «coletivo». Mantêm-se (pronunciam-se em Portugal): «facto», «contacto», «pacto», «compacto», «convicção», «ficção», «egípcio», «núpcias», «rapto», «adepto». Variam conforme a pronúncia (ambas corretas): «setor»/«sector», «caráter»/«carácter», «dicção»/«dição». Em Portugal só «perspetiva» (no Brasil, «perspectiva»). Note: em Portugal «receção», «conceção», «perceção» perderam o «p», que no Brasil se pronuncia («recepção»).',
      c:'O teste é a pronúncia culta em Portugal: se se ouve, escreve-se. Por isso Portugal escreve «facto» e o Brasil «fato»; Portugal «receção» e o Brasil «recepção». Atenção às famílias: «Egito» mas «egípcio» (o «p» ouve-se no adjetivo).',
      x:['«A ação decorre no Egito.» (antes: «acção», «Egipto»)', '«É um facto: o contacto foi feito.» (mantêm-se em Portugal)', '«Fomos à receção do hotel.» (Brasil: «recepção»)'],
      s:['Acordo Ortográfico de 1990', 'Português de Portugal e do Brasil: ortografia'] },
    { n:'Maiúsculas e minúsculas', a:'Meses, estações, pontos cardeais, títulos, tratamentos',
      d:'A maiúscula inicial marca nomes próprios, o início de frase e alguns usos de respeito ou de convenção. O Acordo de 1990 passou várias palavras à minúscula e tornou outras facultativas.',
      u:'Minúscula obrigatória: meses e estações («janeiro», «outono»), dias da semana («domingo»), pontos cardeais quando indicam direção («para norte»), «fulano», «sicrano». Maiúscula: nomes próprios de pessoas, lugares, instituições, festas («Natal», «Páscoa»), regiões designadas pelos pontos cardeais («o Norte», «o Sul»), períodos históricos («o Renascimento»). Facultativo: títulos de livros a partir da segunda palavra («Memorial do convento» ou «Memorial do Convento»), formas de tratamento («senhor doutor» ou «Senhor Doutor»), domínios do saber («português» ou «Português» como disciplina), categorizadores de vias e edifícios («rua da Prata» ou «Rua da Prata», «igreja de São Roque» ou «Igreja»).',
      c:'Num livro, escolha uma solução para cada caso facultativo e mantenha-a. As maiúsculas de respeito em excesso («o Pai disse», «a Avó») soam a texto escolar, salvo quando o narrador as usa como marca de voz.',
      x:['«Chegaram em setembro, numa segunda-feira de outono.»', '«Foi viver para o Norte, a trinta quilómetros a norte do Porto.»', '«Leu *Os Maias* nas férias da Páscoa.»'],
      s:['Maiúsculas depois da pontuação', 'Acordo Ortográfico de 1990'] },
    { n:'Português de Portugal e do Brasil: ortografia', a:'Grafias duplas · facto/fato · António/Antônio',
      d:'Mesmo depois do Acordo de 1990, há palavras que se escrevem de forma diferente em Portugal e no Brasil, porque se pronunciam de forma diferente. O Acordo aceita as duas grafias, cada uma na sua norma.',
      u:'Escreva sempre a forma portuguesa: «facto» (BR «fato»), «contacto» («contato»), «receção» («recepção»), «António» («Antônio»), «género» («gênero»), «económico» («econômico»), «académico» («acadêmico»), «bebé» («bebê»), «polémica» («polêmica»), «secção» («seção»), «connosco» («conosco»), «registo» (nome; BR «registro»), «húmido» («úmido»), «anónimo» («anônimo»), «ténis» («tênis»)… e as formas verbais «amámos» (passado).',
      c:'Os corretores automáticos configurados para português do Brasil «corrigem» as formas portuguesas. Confirme que o processador de texto está em «Português (Portugal)». Num diálogo de uma personagem brasileira, a grafia continua a ser a portuguesa; a voz faz-se pelo léxico e pela sintaxe («você está fazendo»), não pela ortografia.',
      x:['«O género do romance é polémico.» (BR: «gênero», «polêmico»)', '«Fica connosco e mantém o contacto.» (BR: «conosco», «contato»)'],
      s:['Consoantes mudas', 'Vocabulário de Portugal e do Brasil', 'Regras de acentuação'] },
    { n:'Vocabulário de Portugal e do Brasil', a:'comboio/trem · autocarro/ônibus · ecrã/tela · telemóvel/celular',
      d:'Muitas coisas do dia a dia têm nomes diferentes nas duas normas. Num romance passado em Portugal, o léxico brasileiro (ou o decalque do inglês) soa estranho ao leitor português — e o contrário também.',
      u:'Portugal / Brasil: comboio / trem; autocarro / ônibus; elétrico / bonde; ecrã / tela; rato / mouse; telemóvel / celular; casa de banho / banheiro; pequeno-almoço / café da manhã; equipa / time; fato / terno; camisola / suéter; frigorífico / geladeira; talho / açougue; sumo / suco; rapariga / moça (em Portugal, «rapariga» é neutro); miúdo / garoto; propina / mensalidade escolar; constipação / resfriado; peão / pedestre; passadeira / faixa de pedestres; guiar ou conduzir / dirigir; apanhar o autocarro / pegar o ônibus; estar a fazer / estar fazendo.',
      c:'Algumas palavras têm sentidos diferentes e podem causar equívocos sérios («rapariga», «propina», «puto», «bicha» — em Portugal, «fila»). Em ficção, use o léxico como marca da origem e da época de cada personagem, de forma coerente.',
      x:['«Apanhou o elétrico 28 até à Graça.» (BR: «Pegou o bonde»)', '«— Estou a ver — disse ele.» (BR: «Estou vendo»)'],
      s:['Português de Portugal e do Brasil: ortografia', 'Regionalismo', 'Registo de língua', 'Gerúndio e «a + infinitivo»'] }
  ]},

  { name:'Confusões frequentes', items:[
    { n:'Confusões frequentes: à, há, a', a:'Contração, verbo haver e preposição',
      d:'Três palavras que soam igual e têm funções diferentes: «à» (preposição «a» + artigo «a»), «há» (verbo haver) e «a» (preposição, artigo ou pronome).',
      u:'«Há» para tempo passado e existência: «há três anos», «há gente lá fora». «A» para tempo futuro ou distância: «daqui a três anos», «a dez quilómetros». «À» quando a preposição «a» se junta ao artigo feminino: «vou à praia» (vou a + a praia), «à noite», «à pressa». Teste: troque por uma palavra masculina — se der «ao», é «à» («vou ao cinema» → «vou à praia»).',
      c:'«Há anos atrás» é redundante: «há anos» ou «anos atrás». Não há «à» antes de verbos («começou a chover»), antes de palavras masculinas, nem antes de pronomes pessoais («referiu-se a ela»).',
      x:['«Há dez anos que não vem à aldeia.»', '«Daqui a dez anos, a aldeia já não existe.»', '«Chegou à meia-noite, a pé.»'],
      s:['Confusões frequentes: porque, por que, porquê', 'Haver impessoal'] },
    { n:'Confusões frequentes: porque, por que, porquê', a:'Em Portugal: «porque» também nas perguntas',
      d:'Quatro formas com usos distintos. Em Portugal, a pergunta direta faz-se normalmente com «porque», junto — ao contrário do Brasil, que escreve «por que».',
      u:'«Porque» (junto): na resposta e na causa («Saí porque estava calor.») e, em Portugal, na pergunta («Porque saíste?»). «Por que» (separado): quando equivale a «pelo qual», «pela qual», «por qual» («A razão por que saí é simples.», «Por que motivo saíste?»). «Porquê» (com acento): no fim da frase, antes de ponto, e quando é nome («Saíste porquê?», «Não sei o porquê disto.»). «Por quê» separado e com acento é uso brasileiro.',
      c:'Antes de um verbo, não escreva «porquê» no início da pergunta («Porquê saíste?») — é «Porque saíste?». Sozinho, ou antes de um nome sem verbo, é «Porquê»: «Porquê?», «Porquê tanta pressa?».',
      x:['«— Porque não vieste?» «— Porque choveu.»', '«— Não vieste. Porquê?»', '«Ninguém percebeu o porquê da decisão.»', '«Esse é o caminho por que passámos.»'],
      s:['Confusões frequentes: à, há, a', 'Português de Portugal e do Brasil: ortografia'] },
    { n:'Confusões frequentes: palavras parecidas', a:'Parónimos e homófonos',
      d:'Palavras que se escrevem ou se dizem de forma parecida e têm sentidos diferentes. Um corretor automático não as apanha, porque ambas existem.',
      u:'«Comprimento» (medida) / «cumprimento» (saudação, ato de cumprir). «Eminente» (ilustre) / «iminente» (prestes a acontecer). «Descriminar» (tirar a culpa) / «discriminar» (distinguir, segregar). «Ratificar» (confirmar) / «retificar» (corrigir). «Tráfego» (trânsito) / «tráfico» (comércio ilegal). «Despensa» (onde se guarda a comida) / «dispensa» (licença). «Concerto» (música) / «conserto» (reparação). «Coser» (com agulha) / «cozer» (ao lume). «Censo» (recenseamento) / «senso» (juízo). «Cela» (prisão) / «sela» (do cavalo). «Acento» (sinal) / «assento» (cadeira). «Sessão» (reunião) / «secção» (parte) / «cessão» (ato de ceder). «Mal» (contrário de bem) / «mau» (contrário de bom). «Ouve» (ouvir) / «houve» (haver). «Viagem» (nome) / «viajem» (verbo: «que eles viajem»). «Ora» / «hora».',
      c:'«Mal» e «mau»: teste trocando por «bem» e «bom» — «sentiu-se mal» (bem), «um mau dia» (bom dia). «Senão» (caso contrário, exceto) / «se não» (se + não): «Despacha-te, senão perdes o comboio.» / «Se não chover, vamos.».',
      x:['«O cumprimento do contrato era iminente.»', '«Cozeu as batatas e coseu o botão.»', '«Faz-lhe mal; é um mau hábito.»', '«Na secção de livros, houve uma sessão de autógrafos.»'],
      s:['Confusões frequentes: expressões', 'Escolha lexical'] },
    { n:'Confusões frequentes: expressões', a:'ao encontro de / de encontro a · a fim de / afim · acerca de / há cerca de',
      d:'Expressões fixas que mudam de sentido com uma letra ou uma preposição.',
      u:'«Ao encontro de» = a favor de, para junto de («A proposta vai ao encontro do que pedi.»). «De encontro a» = contra, em choque com («O carro foi de encontro ao muro.»). «A fim de» = para («Saiu cedo a fim de apanhar o comboio.») / «afim» = semelhante, parente («temas afins»). «Acerca de» = sobre / «há cerca de» = faz aproximadamente / «a cerca de» = a uma distância aproximada. «Em vez de» = em lugar de / «ao invés de» = ao contrário de. «De mais» = em excesso, oposto a «de menos» («comeu bolos de mais») / «demais» = os outros («os demais convidados») e, também, «demasiado» («é bom demais»). «Afinal» / «a final» (raro). «Por isso» (sempre separado).',
      c:'«Ao encontro de» e «de encontro a» significam o contrário um do outro: trocá-los inverte o que se diz.',
      x:['«A decisão foi de encontro ao que tínhamos combinado.» (contrariou-o)', '«Falou acerca do livro há cerca de uma hora.»', '«Em vez de sair, ficou.»'],
      s:['Confusões frequentes: palavras parecidas', 'Lugar-comum'] }
  ]},

  { name:'Formas verbais difíceis', items:[
    { n:'Verbos irregulares mais traiçoeiros', a:'intervir, reaver, requerer, precaver, pôr, haver, ver/vir',
      d:'Alguns verbos irregulares produzem erros frequentes, porque se conjugam por analogia com outros que não lhes servem de modelo.',
      u:'«Intervir» conjuga-se como «vir»: «ele interveio», «se eu intervier». «Reaver» só tem as formas em que «haver» tem «v»: «reouve», «reaveremos» (não «reavejo»). «Requerer» não é «querer»: «eu requeiro», «ele requereu». «Precaver» é defetivo: «precavemos», «precavi-me» (não «precavejo»). «Ver» e «vir» no futuro do conjuntivo: «quando eu vir» (ver), «quando eu vier» (vir). «Pôr» e derivados: «se ele propuser», «quando eles compuserem». «Haver» na 2.ª pessoa: «tu hás de», nunca «hades».',
      c:'O futuro do conjuntivo de «ver» — «se eu o vir», «quando o virmos» — é dos erros mais comuns («se eu o ver»). Na 2.ª pessoa do singular do pretérito perfeito não há «s» final: «tu fizeste», «tu foste» (não «fizestes», «fostes», que são da 2.ª do plural).',
      x:['«Se o vires, diz-lhe que liguei.»', '«Quando vieres, traz o livro.»', '«O vizinho interveio a tempo.»', '«Tu disseste que vinhas.»'],
      s:['Tempos e modos: o conjuntivo', 'Haver impessoal'] }
  ]}
  ]});

/* ============ SINTAXE ============ */
SUPPORT.push({ key:'sintaxe', name:'Sintaxe', kicker:'Sintaxe',
  intro:'Como se constroem as frases: a ordem das palavras, a concordância, a colocação dos pronomes, os tempos e modos dos verbos, as preposições que cada verbo pede. Usa-se a terminologia do Dicionário Terminológico, a que se ensina nas escolas portuguesas, e as regras do português europeu, que em vários pontos (pronomes, gerúndio, tratamento) se afasta do Brasil. Para a pontuação da frase, veja a secção «Pontuação».',
  groups:[

  { name:'A frase e as suas funções', items:[
    { n:'Funções sintáticas', a:'Sujeito, predicado, complementos, modificadores, vocativo',
      d:'As funções que os grupos de palavras desempenham ao nível da frase, segundo o Dicionário Terminológico (que define também, dentro dos grupos, o complemento do nome, o complemento do adjetivo e o modificador do nome, restritivo ou apositivo): sujeito, predicado, complemento direto, complemento indireto, complemento oblíquo, complemento agente da passiva, predicativo do sujeito, predicativo do complemento direto, modificador e vocativo.',
      u:'Sujeito: de quem se diz algo («A avó dormia»). Complemento direto: o que o verbo pede sem preposição («Leu a carta» → «leu-a»). Complemento indireto: o destinatário, com «a» («Deu a carta à neta» → «deu-lhe»). Complemento oblíquo: pedido pelo verbo, com outras preposições ou advérbio («Gosta de chá», «Mora em Lisboa»). Predicativo do sujeito: com verbos como ser, estar, parecer, ficar («A casa ficou vazia»). Modificador: acrescento não pedido pelo verbo — tempo, lugar, modo, causa («Ontem, à noite, leu devagar»).',
      c:'Saber a função ajuda a pontuar (não se separa o sujeito do verbo, nem o verbo do complemento direto) e a escolher o pronome certo («vi-o», não «vi-lhe»; «obedeceu-lhe», não «obedeceu-o»).',
      x:['«A Inês» (sujeito) «entregou» (predicado) «a carta» (complemento direto) «ao faroleiro» (complemento indireto) «nessa noite» (modificador).'],
      s:['Vírgula: quando não usar', 'Colocação dos pronomes', 'Regência verbal'] },
    { n:'Ordem das palavras', a:'Sujeito-verbo-complemento e as suas alterações',
      d:'A ordem neutra em português é sujeito, verbo, complementos (SVO). Alterá-la é possível e expressivo: o que se desloca para o início ou para o fim da frase ganha destaque.',
      u:'Anteposição do complemento para dar ênfase: «Esse livro, nunca o li.» (com pronome a retomar). Sujeito depois do verbo, natural com verbos de movimento e existência («Chegou o inverno.», «Faltam duas cadeiras.») e em perguntas («Onde mora a tua irmã?»). O fim da frase é a posição de maior peso: guarde para lá a palavra mais importante.',
      c:'Inversões gratuitas soam a tradução ou a poesia de escola («Do mar o cheiro sentia ele»). O hipérbato funciona quando há uma razão — ritmo, ênfase, voz da personagem.',
      x:['Neutro: «O faroleiro acendeu a luz.»', 'Ênfase no complemento: «A luz, acendeu-a o faroleiro.»', 'Sujeito no fim: «Acendeu-se, por fim, a luz do farol.»'],
      s:['Hipérbato', 'Ênfase e fim de frase', 'Frase periódica e frase cumulativa'] },
    { n:'Coordenação e subordinação', a:'Frase simples e frase complexa · orações',
      d:'A frase complexa junta orações de duas maneiras: por coordenação (lado a lado, com a mesma importância: «e», «mas», «ou», «portanto») ou por subordinação (uma oração depende de outra: «quando», «porque», «que», «embora», «se»).',
      u:'Coordenação dá um ritmo de enumeração e de sucessão («Abriu a porta, olhou e saiu.»). Subordinação hierarquiza, explica, condiciona («Quando abriu a porta, percebeu que alguém tinha saído.»). Em ficção, a coordenação aproxima-se da fala e da ação; a subordinação, do pensamento e da análise.',
      c:'Encadear muitas subordinadas («que… que… que…») torna a frase difícil de seguir; parta-a. Coordenar orações que deviam estar subordinadas apaga a relação entre elas.',
      x:['Coordenação: «Chovia e ninguém saiu.»', 'Subordinação causal: «Como chovia, ninguém saiu.»', 'Encadeado difícil: «Disse que achava que a mulher que tinha visto era a que…» → partir em duas frases.'],
      s:['Parataxe e hipotaxe', 'Vírgula com conjunções', 'Frase longa'] }
  ]},

  { name:'Concordância', items:[
    { n:'Concordância verbal: casos difíceis', a:'A maioria dos… · fui eu que · mais de um · nem… nem',
      d:'O verbo concorda com o sujeito em pessoa e número. Os casos difíceis são os sujeitos coletivos, partitivos, compostos e os construídos com «que» e «quem».',
      u:'Expressões partitivas («a maioria de», «grande parte de», «metade de») + plural: o verbo pode ficar no singular (concorda com o núcleo) ou no plural (com o sentido): «A maioria dos alunos chegou/chegaram». «Fui eu que fiz» (o verbo concorda com «eu») / «Fui eu quem fez» (com «quem», 3.ª pessoa) — ambos corretos. «Mais de um» + singular: «Mais de um aluno faltou.». Sujeito composto antes do verbo: plural («O pai e a mãe saíram.»); depois do verbo, pode concordar com o mais próximo («Saiu o pai e a mãe.» é aceite, mas o plural é mais seguro). «Nem um nem outro» + singular ou plural. «Um dos que» + plural: «É um dos que mais trabalham.».',
      c:'Com «haver» no sentido de existir, o verbo fica no singular: «Houve problemas», nunca «Houveram problemas» (ver «Haver impessoal»). Coletivos no singular pedem verbo no singular: «A multidão gritou.».',
      x:['«A maior parte dos convidados já tinha saído.»', '«Fomos nós que pagámos.» / «Fomos nós quem pagou.»', '«Mais de um vizinho ouviu o tiro.»'],
      s:['Haver impessoal', 'Funções sintáticas'] },
    { n:'Haver impessoal', a:'Houve, há, havia — sempre no singular',
      d:'O verbo «haver», quando significa «existir» ou indica tempo decorrido, não tem sujeito: é impessoal e fica sempre na 3.ª pessoa do singular — e o mesmo acontece aos verbos auxiliares que o acompanham.',
      u:'«Há muitas pessoas», «Houve dois acidentes», «Havia três cartas», «Deve haver soluções» (e não «devem haver»), «Vai haver festas». O mesmo com «fazer» no sentido de tempo: «Faz dez anos que partiu.».',
      c:'«Existir» é pessoal e concorda: «Existem soluções» / «Há soluções». Ao trocar um pelo outro, mude a concordância. «Haver» como auxiliar (com particípio) concorda normalmente: «Eles haviam saído.».',
      x:['«Houve gritos na rua.»', '«Podia haver outras explicações.»', '«Havia anos que não se viam.»'],
      s:['Concordância verbal: casos difíceis', 'Confusões frequentes: à, há, a'] },
    { n:'Concordância nominal', a:'Adjetivos, particípios e numerais',
      d:'O adjetivo e o particípio concordam em género e número com o nome a que se referem. Os casos difíceis são os adjetivos que se referem a vários nomes, e expressões como «meio», «bastante», «obrigado», «anexo», «é proibido».',
      u:'Adjetivo depois de vários nomes: plural (masculino se houver um masculino: «o casaco e a camisa brancos») ou concordância com o mais próximo («o casaco e a camisa branca», aceite). «Meio» como advérbio é invariável («meio cansada»); como adjetivo concorda («meia hora»). «Obrigado» concorda com quem agradece («— Obrigada — disse ela.»). «É proibido entrada» (sem artigo, invariável) / «É proibida a entrada» (com artigo, concorda).',
      c:'«Menos» não tem feminino: «menos gente», nunca «menas». «Bastante» concorda quando é quantificador («bastantes livros») e não concorda quando é advérbio («livros bastante caros»).',
      x:['«Ela estava meio adormecida, à espera havia meia hora.»', '«— Muito obrigada — respondeu a avó.»', '«Comprou bastantes livros, bastante caros.»'],
      s:['Concordância verbal: casos difíceis', 'Funções sintáticas'] }
  ]},

  { name:'Pronomes e tratamento', items:[
    { n:'Colocação dos pronomes', a:'Ênclise, próclise e mesóclise · disse-lhe / não lhe disse / dir-lhe-ei',
      d:'Em português europeu, o pronome átono (me, te, se, o, a, lhe, nos, vos, lhes) vai, em regra, depois do verbo, ligado por hífen (ênclise): «Disse-lhe a verdade.». Vai antes do verbo (próclise) quando certas palavras o «atraem». No futuro e no condicional, vai no meio do verbo (mesóclise).',
      u:'Próclise com: negação («Não lhe disse»), advérbios como «já», «ainda», «também», «sempre», «só», «bem», «talvez» («Já o vi»), pronomes relativos e interrogativos («Quem te disse?», «O livro que me deste»), conjunções subordinativas («Quando o vir»), quantificadores («Todos se riram», «Alguém me chamou»), e frases exclamativas e optativas («Deus te ouça!»). Mesóclise: futuro e condicional sem palavra atrativa («Dir-te-ei», «Encontrar-nos-íamos»); com palavra atrativa, próclise («Não te direi»).',
      c:'Começar a frase com o pronome («Me disse que…») é uso brasileiro; em Portugal soa errado. Na fala corrente portuguesa, a mesóclise é pouco usada («vou dizer-te» em vez de «dir-te-ei»), mas a próclise antes do verbo no futuro («te direi» sem atrator) nunca está correta. As formas «o», «a» mudam depois de certas terminações: «fá-lo», «dizê-lo», «amam-no», «põe-no».',
      x:['«Contou-me tudo.» / «Não me contou nada.»', '«Já te tinha dito.»', '«Se o encontrares, diz-lho.»', '«Dir-lhe-ia, se pudesse.»'],
      t:'A colocação dos pronomes é uma das marcas mais rápidas de uma personagem brasileira, ou de um narrador influenciado por traduções. Registe a escolha na ficha da Personagem.',
      s:['Hífen em compostos e locuções', 'Formas de tratamento', 'Funções sintáticas'] },
    { n:'O e lhe: complemento direto e indireto', a:'Vi-o · disse-lhe · obedeceu-lhe',
      d:'O pronome «o/a/os/as» substitui o complemento direto; «lhe/lhes» substitui o complemento indireto (o destinatário, introduzido por «a»). Trocar um pelo outro é um erro muito frequente.',
      u:'Faça a pergunta ao verbo: «ver alguém» (vi-o), «ajudar alguém» (ajudei-o), «convidar alguém» (convidei-a), «conhecer alguém» (conheço-o); «dizer a alguém» (disse-lhe), «obedecer a alguém» (obedeci-lhe), «telefonar a alguém» (telefonei-lhe), «agradecer a alguém» (agradeci-lhe). Quando os dois se juntam, contraem: lhe + o = «lho» («Dei-lho»).',
      c:'«Vi-lhe ontem», «ajudei-lhe», «convidei-lhe» estão errados. Em português europeu, «lhe» refere-se à 3.ª pessoa (incluindo «você»): «Disse-lhe, a si, que…». Em Portugal, «você» trata-se com «o/a» e «lhe» («Vi-o ontem, senhor doutor»), não com «te».',
      x:['«Encontrei a Inês e cumprimentei-a.»', '«Encontrei a Inês e telefonei-lhe à noite.»', '«— Devolves-me o livro? — Devolvo-to amanhã.»'],
      s:['Colocação dos pronomes', 'Regência verbal', 'Funções sintáticas'] },
    { n:'Tratamento e concordância', a:'tu · você · o senhor · vós · vocês',
      d:'Em Portugal, o tratamento por «tu» (íntimo) usa a 2.ª pessoa; «você», «o senhor», «a senhora» e o nome próprio usam a 3.ª pessoa. No plural, «vocês» usa a 3.ª do plural; «vós» sobrevive em algumas regiões do Norte e em textos religiosos e literários antigos.',
      u:'Concordância com «você»: verbo, pronomes e possessivos na 3.ª pessoa («Você trouxe o seu casaco? Vi-o ontem.»). Com «tu»: 2.ª pessoa («Trouxeste o teu casaco? Vi-te ontem.»). Misturar os dois («Você trouxe o teu casaco?») é marca de fala descuidada — útil para caracterizar, mas não na voz do narrador.',
      c:'Em Portugal, «você» pode soar distante ou pouco delicado; em muitos contextos, prefere-se o tratamento pelo nome ou pelo título, sem pronome («A Inês quer café?», «O senhor doutor quer café?»). Ver também a ficha «Formas de tratamento», nos Recursos Estilísticos.',
      x:['Tu: «Trazes o teu irmão?»', 'Você: «Traz o seu irmão?»', 'Pelo nome: «A Inês traz o irmão?»'],
      s:['Formas de tratamento', 'Colocação dos pronomes', 'Registo de língua'] }
  ]},

  { name:'Verbos: tempos, modos e regência', items:[
    { n:'Tempos e modos: o conjuntivo', a:'Presente, pretérito e futuro do conjuntivo (no Brasil, «subjuntivo»)',
      d:'O conjuntivo é o modo da dúvida, do desejo, da possibilidade e da hipótese, e é pedido por muitas expressões («espero que», «talvez», «embora», «se», «quando» com valor futuro). Em Portugal chama-se «conjuntivo»; no Brasil, «subjuntivo».',
      u:'Presente: «Espero que venhas.», «Talvez chova.». Pretérito imperfeito: «Se eu soubesse, tinha vindo.», «Queria que ele ficasse.». Futuro (vivo em português e em galego, quase desaparecido nas outras línguas românicas): «Quando chegares, liga.», «Se vires a Inês, avisa-a.», «Faz o que quiseres.». Em ficção, o conjuntivo é essencial nas hipóteses e nos desejos das personagens — e o seu desaparecimento numa fala é uma marca de registo popular.',
      c:'Erros comuns: «se eu ver» (→ «se eu vir»), «quando eu fazer» (→ «quando eu fizer»), «espero que vens» (→ «que venhas»). Na fala corrente, o condicional é frequentemente substituído pelo imperfeito do indicativo («Se pudesse, ia» em vez de «iria») — em Portugal isso é perfeitamente aceite, sobretudo em diálogo.',
      x:['«Se tivesses chegado mais cedo, tinha-lo visto.»', '«Quando a maré baixar, vamos ao cais.»', '«Oxalá ela volte.»'],
      s:['Verbos irregulares mais traiçoeiros', 'Tempos verbais da narração'] },
    { n:'Gerúndio e «a + infinitivo»', a:'estar a fazer · estar fazendo',
      d:'Para indicar uma ação em curso, o português europeu usa «estar a + infinitivo» («Estou a ler»); o Brasil, o Alentejo e partes do Algarve e das ilhas usam o gerúndio («Estou lendo»).',
      u:'Na voz de um narrador português, use «a + infinitivo»: «Estava a chover», «Continuou a escrever», «Ficou a olhar». O gerúndio continua normal em orações adverbiais («Saiu, batendo com a porta», «Chegando a casa, deitou-se») e é uma marca possível de uma personagem alentejana ou brasileira.',
      c:'O «gerundismo» («vou estar enviando o documento») é um decalque do inglês, condenado nas duas normas. Gerúndios em série tornam a frase pesada.',
      x:['«Estava a ler quando o telefone tocou.»', 'Personagem alentejana: «— Tava-se fazendo tarde, compadre.»', 'Adverbial: «Abrindo a janela, sentiu o cheiro do mar.»'],
      s:['Vocabulário de Portugal e do Brasil', 'Vírgula com gerúndio e particípio', 'Regionalismo'] },
    { n:'Regência verbal', a:'As preposições que cada verbo pede',
      d:'Muitos verbos pedem uma preposição determinada, e alguns mudam de sentido conforme a preposição. É uma das áreas em que mais se nota a diferença entre o português europeu e o do Brasil, e em que mais se nota a influência do inglês.',
      u:'Exemplos de Portugal: «assistir a» (presenciar: «assistiu ao jogo»); «obedecer a»; «preferir X a Y» (não «preferir X do que Y»); «ir a» (ida breve: «vou ao médico») / «ir para» (mudança: «foi para Paris viver»); «chegar a» («chegou a casa», não «chegou em casa»); «morar em»; «lembrar-se de» / «lembrar algo»; «esquecer-se de» / «esquecer algo»; «gostar de»; «namorar com» (corrente em Portugal) ou «namorar alguém»; «responder a»; «implicar» (trazer como consequência: «implica riscos», sem «em»); «aspirar a» (desejar) / «aspirar» (inspirar).',
      c:'«Chegar em», «ir no médico», «assistir o jogo» são usos brasileiros. «Preferir mais» é redundante. Decalques do inglês: «apostar em» é correto; «focar em» é aceite mas «concentrar-se em» é mais natural; «realizar» no sentido de «perceber» é anglicismo («realizou que estava sozinho» → «percebeu»).',
      x:['«Prefiro o mar à montanha.»', '«Chegou a casa às três.»', '«Esqueceu-se do guarda-chuva.» / «Esqueceu o guarda-chuva.»', '«Assistiram ao concerto na primeira fila.»'],
      s:['O e lhe: complemento direto e indireto', 'Funções sintáticas', 'Estrangeirismo'] },
    { n:'Infinitivo pessoal', a:'Para fazermos · ao chegarem · é melhor saíres',
      d:'O português tem um infinitivo que se flexiona em pessoa e número — uma raridade entre as línguas românicas: «para eu fazer», «para tu fazeres», «para nós fazermos», «para eles fazerem».',
      u:'Use-o quando o sujeito do infinitivo é diferente do da oração principal, ou para tornar claro quem pratica a ação: «Deu-lhes o mapa para não se perderem.», «É melhor saíres já.», «Ao chegarmos, já tinham jantado.».',
      c:'Com o mesmo sujeito e com auxiliares («poder», «querer», «dever», «ir»), o infinitivo não se flexiona: «Eles querem sair» (não «querem saírem»). Flexionar em excesso soa pesado; omitir quando é preciso cria ambiguidade.',
      x:['«Trouxe o livro para leres.»', '«Antes de partirmos, a avó abençoou-nos.»'],
      s:['Concordância verbal: casos difíceis', 'Ambiguidade'] }
  ]},

  { name:'Erros e vícios de construção', items:[
    { n:'Pleonasmos e redundâncias', a:'subir para cima · há anos atrás · elo de ligação',
      d:'O pleonasmo vicioso repete, sem intenção, uma ideia já contida noutra palavra. Distingue-se do pleonasmo expressivo (a figura de estilo), que repete de propósito para dar força.',
      u:'Corte: «subir para cima», «descer para baixo», «entrar para dentro», «sair para fora», «há anos atrás», «elo de ligação», «encarar de frente», «surpresa inesperada», «planos para o futuro», «a razão é porque», «hemorragia de sangue», «repetir de novo», «monopólio exclusivo», «recriar de novo», «conviver juntos».',
      c:'Em diálogo, a redundância pode ser marca da personagem; na voz do narrador, é descuido. Antes de cortar, veja se a repetição tem função (ênfase, ritmo, oralidade).',
      x:['«Há três anos atrás» → «Há três anos» ou «Três anos atrás».', 'Expressivo: «Vi-o com estes olhos que a terra há de comer.»'],
      s:['Pleonasmo', 'Repetição e sinónimos', 'Revisão por camadas'] },
    { n:'Ambiguidade sintática', a:'Frases com duas leituras',
      d:'Uma frase é sintaticamente ambígua quando a sua construção permite duas interpretações: um pronome que pode referir-se a duas pessoas, um modificador que pode ligar-se a dois termos, um «que» com dois antecedentes possíveis.',
      u:'Leia como um estranho. Pronomes: «O Tomás disse ao Duarte que ele tinha de partir» — quem parte? Reformule: «O Tomás disse ao Duarte: — Tens de partir.». Modificadores: «Vi o homem com binóculos» — quem tem os binóculos? Relativas: «A filha do vizinho que chegou ontem» — quem chegou?',
      c:'A ambiguidade involuntária é um dos defeitos mais difíceis de ver no próprio texto; a voluntária pode ser um recurso (o leitor fica sem saber, de propósito).',
      x:['Ambíguo: «A Inês viu a avó a chorar na cozinha.» (quem chorava?)', 'Claro: «A Inês viu, na cozinha, a avó a chorar.»'],
      s:['Ambiguidade', 'Vírgula e orações relativas'] },
    { n:'Onde, que e cujo', a:'Uso abusivo de «onde» · «que» sem função · «cujo»',
      d:'Os pronomes relativos ligam orações e têm regras próprias. «Onde» só se usa para lugares; «cujo» exprime posse e concorda com o que é possuído; o «que» relativo precisa da preposição que o verbo pede.',
      u:'«Onde» = no lugar em que: «a casa onde nasceu». Para tempo ou situações, «em que»: «o dia em que partiu» (não «o dia onde partiu»), «uma situação em que…». «Cujo»: «a mulher cujo filho partiu» (sem artigo depois de «cujo»). Preposição antes do relativo: «o livro de que te falei» (falar de), «a pessoa com quem casou» (casar com), «o cargo a que aspira» (aspirar a).',
      c:'O «que» sem preposição («o livro que te falei») é corrente na fala e serve para caracterizar personagens, mas não na voz do narrador. «Cujo o» é erro: «cujo filho», nunca «cujo o filho».',
      x:['«Foi o verão em que tudo mudou.»', '«O farol, cuja luz se via de Sagres, apagou-se.»', '«É a cidade de que mais gosto.»'],
      s:['Vírgula e orações relativas', 'Regência verbal'] },
    { n:'Anglicismos de construção', a:'Decalques do inglês na frase',
      d:'Construções copiadas do inglês, muitas vezes por influência de traduções, legendas e da linguagem técnica. Não são palavras estrangeiras, mas frases estrangeiras com palavras portuguesas.',
      u:'Evite: «fazer sentido» em excesso (prefira «ter lógica», «perceber-se»), «no final do dia» (= afinal), «realizar» por «perceber», «suportar» por «apoiar», «assumir» por «supor», «eventualmente» por «finalmente», «atualmente» por «na verdade» (inglês «actually»), «ser suposto» («é suposto ele vir» → «ele devia vir»), voz passiva em excesso («foi decidido por nós» → «decidimos»), possessivos desnecessários («levantou a sua mão» → «levantou a mão»), e o adjetivo antes do nome por sistema.',
      c:'Algumas destas construções já entraram no uso e são aceites; o problema é a acumulação, que dá ao texto um tom de tradução apressada. Os possessivos com partes do corpo são o sinal mais claro.',
      x:['«Abriu os seus olhos e passou a sua mão pelo seu cabelo.» → «Abriu os olhos e passou a mão pelo cabelo.»', '«Eventualmente, ele chegou.» (= talvez) / «Finalmente, ele chegou.»'],
      s:['Estrangeirismo', 'Regência verbal', 'Voz ativa e voz passiva'] }
  ]}
  ]});

/* ---- Mais fichas de Ortografia e de Sintaxe ---- */
(() => {
  const into = (key, group, items) => { const sec = SUPPORT.find(s => s.key === key); let g = sec.groups.find(x => x.name === group);
    if (!g){ g = {name:group, items:[]}; sec.groups.push(g); } g.items.push(...items); };

  into('ortografia', 'Letras e grafias', [
    { n:'Grafia dos sons: x ou ch, s, ss, ç ou z, g ou j', a:'Letras diferentes para o mesmo som',
      d:'Vários sons do português escrevem-se com letras diferentes, e a escolha depende sobretudo da origem da palavra. Não há regra que dispense o dicionário, mas há padrões que ajudam.',
      u:'x / ch: «xaile», «enxada», «bruxa», «caixa» (x depois de ditongo e de en- costuma ser regra) / «chave», «chuva», «chá» (ch vem muitas vezes de pl-, cl-, fl- latinos: «chave» < clave). s / z entre vogais: «casa», «mesa», «Teresa» / «azeite», «prazer», «certeza» (o sufixo de qualidade é -eza: «beleza», «tristeza»; o de origem é -esa: «portuguesa», «francesa»). ss / ç: «passo», «missa» / «força», «lição»; nunca ç antes de e e i. g / j antes de e e i: «gente», «gelo», «viagem» (nome) / «jeito», «majestade», «viajem» (verbo), «laranjeira» (de laranja). Os nomes em -agem escrevem-se com g; o verbo «viajar» mantém o j em toda a conjugação.',
      c:'Os erros mais frequentes: «previlégio» (privilégio), «beneficiente» (beneficente), «excessão» (exceção), «concerteza» (com certeza), «derrepente» (de repente), «à priori» (a priori, sem acento), «mendingo» (mendigo), «cidadões» (cidadãos).',
      x:['«A portuguesa admirou a beleza da paisagem.»', '«Fizeram uma viagem; espero que viajem bem.»', '«Com certeza, de repente, a exceção.»'],
      s:['Palavras divergentes', 'Confusões frequentes: palavras parecidas'] },
    { n:'Nomes próprios, topónimos e exónimos', a:'Nova Iorque · Pequim · Moscovo · Londres',
      d:'Muitas cidades e países estrangeiros têm nome português (exónimo), que é o que se usa em Portugal. Os nomes de pessoas e lugares portugueses seguem as regras ortográficas, com exceções consagradas nos apelidos.',
      u:'Exónimos correntes em Portugal: Nova Iorque, Pequim, Moscovo, Londres, Bruxelas, Genebra, Colónia, Munique, Florença, Veneza, Varsóvia, Estocolmo, Copenhaga, Helsínquia, Cracóvia, Xangai, Tóquio, Banguecoque, Joanesburgo. Países: Irão, Quénia, Ruanda, Vietname, Singapura, Zimbabué. Os apelidos podem conservar grafias antigas (Sousa/Souza, Athayde, Thomaz), mas um nome próprio comum segue a ortografia atual (Inês, Tomás, Luís).',
      c:'Os exónimos brasileiros diferem em vários casos (Moscou, Copenhague, Irã, Quênia, Vietnã): num texto português, use os portugueses. Num romance passado noutro tempo, verifique o nome da época (Leninegrado, Constantinopla, Bombaim).',
      x:['«Voou de Lisboa para Nova Iorque, com escala em Copenhaga.»', '«Em 1910, ainda se dizia Constantinopla.»'],
      s:['Vocabulário de Portugal e do Brasil', 'Português de Portugal e do Brasil: ortografia'] },
    { n:'Estrangeirismos e aportuguesamentos', a:'ecrã · futebol · abajur/candeeiro · stress',
      d:'As palavras estrangeiras entram no português de três maneiras: mantêm a grafia original (em itálico), aportuguesam-se («football» → «futebol», «écran» → «ecrã») ou são substituídas por uma palavra portuguesa («mouse» → «rato»). Portugal e o Brasil fazem muitas vezes escolhas diferentes.',
      u:'Prefira o aportuguesamento já fixado em Portugal: ecrã, rato, sítio (na internet, a par de site), bife, futebol, golo, uísque, champanhe, croquete, sanduíche, abajur (raro; em Portugal diz-se candeeiro), clube, estresse (no Brasil; em Portugal usa-se stress, em itálico ou já em redondo). Escreva em itálico as palavras estrangeiras não aportuguesadas (*marketing*, *croissant*, *timing*).',
      c:'O excesso de anglicismos é a marca de uma prosa apressada. Em diálogo, porém, pode caracterizar uma personagem (um gestor, um adolescente).',
      x:['«Marcou um golo no último minuto.» (no Brasil: «gol»)', '«Acendeu o candeeiro e ligou o ecrã.»'],
      s:['Estrangeirismo', 'Vocabulário de Portugal e do Brasil', 'Itálico, negrito e maiúsculas de destaque'] },
    { n:'Numerais por extenso', a:'dezasseis · catorze · mil e um · vigésimo primeiro',
      d:'Em ficção, os números escrevem-se muitas vezes por extenso. Algumas formas são próprias de Portugal.',
      u:'Em Portugal: dezasseis, dezassete, dezanove (Brasil: dezesseis, dezessete, dezenove); catorze (Brasil também quatorze). O «e» liga dezenas e unidades e as centenas às dezenas: «trezentos e vinte e um». Entre o milhar e as centenas, «e» só quando a centena é redonda ou o número acaba aí: «mil e quinhentos», «dois mil e vinte», mas «mil novecentos e setenta». Ordinais: «vigésimo primeiro», «centésimo».',
      c:'«Milhões» concorda no masculino: «dois milhões de pessoas». «Um milhão de euros», nunca «um milhão euros».',
      x:['«Tinha dezassete anos em mil novecentos e setenta e quatro.»', '«O vigésimo primeiro capítulo.»'],
      s:['Números, datas e horas', 'Português de Portugal e do Brasil: ortografia'] },
    { n:'Siglas, acrónimos e símbolos', a:'ONU · Unesco · km · os CTT',
      d:'As siglas leem-se letra a letra (CTT, RTP); os acrónimos leem-se como palavra (NATO, Unesco, sida). As siglas não levam pontos nem plural com s; os acrónimos longos podem escrever-se só com maiúscula inicial.',
      u:'Sem pontos: «a ONU», «os CTT» (não «C.T.T.»). Plural pelo artigo: «as ONG», «os PALOP». Acrónimos lexicalizados podem passar a minúscula: «sida», «radar», «laser». Na primeira ocorrência num texto, escreva o nome por extenso e a sigla entre parênteses. Símbolos de unidades: «km», «kg», «h», sem ponto nem plural.',
      c:'Em Portugal, «NATO» (no Brasil, «OTAN»); «SIDA» ou «sida» (no Brasil, «AIDS»). Numa fala, as siglas leem-se como se dizem: «a Rtp», «os Ctt» não; escreva a sigla normal e confie no leitor.',
      x:['«A Organização das Nações Unidas (ONU) reuniu-se.»', '«Mandou a carta pelos CTT.»'],
      s:['Abreviaturas e pontuação', 'Números, datas e horas'] }
  ]);
  into('ortografia', 'Palavras compostas e plurais', [
    { n:'Plural dos compostos', a:'guarda-chuvas · couves-flor · amores-perfeitos',
      d:'O plural dos nomes compostos com hífen depende das palavras que os formam: só variam os elementos que são nomes ou adjetivos.',
      u:'Verbo + nome: só o nome vai ao plural («guarda-chuvas», «tira-nódoas»). Nome + nome: em geral ambos («couves-flores» ou, quando o segundo especifica, «couves-flor»; «navios-escola»). Nome + adjetivo, adjetivo + nome: ambos («amores-perfeitos», «obras-primas», «más-línguas»). Com preposição (com hífen consagrado): só o primeiro («pés-de-meia»). Palavras invariáveis e advérbios não variam («bem-me-queres» varia no fim; «abaixo-assinados»).',
      c:'Locuções sem hífen depois do Acordo seguem o mesmo princípio: «fins de semana», «mãos de obra».',
      x:['«Esqueceu os guarda-chuvas nos comboios.»', '«Era uma das obras-primas da coleção.»', '«Passaram vários fins de semana no Algarve.»'],
      s:['Hífen em compostos e locuções', 'Concordância nominal'] },
    { n:'Plurais e femininos difíceis', a:'cidadãos, pães, alemães · o/a intérprete · a juíza, a presidente',
      d:'Os nomes em -ão fazem o plural de três maneiras (-ãos, -ães, -ões), conforme a origem; alguns nomes têm feminino irregular ou comum aos dois géneros.',
      u:'Plurais em -ão (vêm das três terminações medievais): -ãos («mãos», «cidadãos», «irmãos», «cristãos»), -ães («pães», «cães», «alemães», «capitães»), -ões («leões», «limões», «corações»). Alguns admitem dois ou três («anciãos/anciães/anciões», «vilãos/vilões»). Femininos: «a juíza», «a ministra», «a presidente» (ou «presidenta», menos usado em Portugal), «a médica»; comuns de dois: «o/a intérprete», «o/a estudante», «o/a jovem».',
      c:'«Cidadões» e «capitãos» são erros frequentes. Os femininos de profissões mudaram com a sociedade: num romance de época, «a senhora doutora» pode ser rara, e isso diz algo sobre a personagem.',
      x:['«Os cidadãos e os capitães ouviram os alemães.»', '«A juíza ouviu a intérprete.»'],
      s:['Do latim ao português: vogais e hiatos', 'Concordância nominal'] }
  ]);

  into('sintaxe', 'Verbos: tempos, modos e regência', [
    { n:'Mais-que-perfeito simples e composto', a:'fizera · tinha feito',
      d:'O pretérito mais-que-perfeito indica uma ação anterior a outra no passado. Tem uma forma simples («fizera», «chegara») e uma composta («tinha feito», «tinha chegado»). Na língua corrente, usa-se quase só a composta; a simples é literária.',
      u:'Num romance narrado no passado, o mais-que-perfeito é a ferramenta das analepses: «Quando chegou, a mãe já tinha saído.». Para uma analepse longa, use-o para entrar na memória e passe ao pretérito perfeito ao fim de duas ou três frases, para não pesar. A forma simples dá um tom literário ou antiquado, útil em certos narradores.',
      c:'Uma página inteira em «tinha feito… tinha dito… tinha ido» torna-se pesada. A forma simples em diálogo soa falsa, salvo numa personagem de linguagem muito cuidada ou antiga.',
      x:['«Nessa manhã, a avó tinha acordado cedo. Abriu as janelas e foi ao quintal…»', 'Literário: «Nunca vira o mar tão calmo.»'],
      s:['Tempos verbais da narração', 'Analepse', 'Tempos e modos: o conjuntivo'] },
    { n:'Discurso indireto: as mudanças', a:'Tempos, pronomes, advérbios',
      d:'Ao passar uma fala do discurso direto para o indireto, mudam os tempos verbais, os pronomes, os possessivos e os advérbios de tempo e de lugar, que passam a ser vistos do ponto de vista do narrador.',
      u:'Presente → imperfeito («— Estou cansada.» → Disse que estava cansada.). Pretérito perfeito → mais-que-perfeito («— Vi-o.» → Disse que o tinha visto.). Futuro → condicional («— Virei amanhã.» → Disse que viria no dia seguinte.). Imperativo → conjuntivo («— Sai!» → Mandou que saísse.). Eu/tu → ele/ela; aqui → ali; hoje → nesse dia; amanhã → no dia seguinte; ontem → na véspera.',
      c:'Misturar os dois discursos sem critério confunde quem fala; quando se quer misturar, isso é o discurso indireto livre, que tem regras próprias.',
      x:['Direto: «— Amanhã volto aqui — disse ele.»', 'Indireto: «Disse que no dia seguinte voltava ali.»'],
      s:['Discurso indireto', 'Discurso direto', 'Discurso indireto livre'] }
  ]);
  into('sintaxe', 'A frase e as suas funções', [
    { n:'Passiva e passiva pronominal', a:'Foi vendida a casa · vendem-se casas',
      d:'A voz passiva põe em evidência quem sofre a ação. Em português há duas: a passiva com «ser» + particípio («A casa foi vendida») e a passiva pronominal com «se» («Vende-se a casa», «Vendem-se casas»).',
      u:'Na passiva pronominal, o verbo concorda com o sujeito (o que é vendido, alugado, arranjado): «Vendem-se casas», «Alugam-se quartos», «Fizeram-se obras». Com verbos que pedem preposição, o «se» é indeterminado e o verbo fica no singular: «Precisa-se de empregados», «Trata-se de questões sérias».',
      c:'«Vende-se casas» e «Aluga-se quartos» estão errados («Vendem-se», «Alugam-se»). A passiva com «ser» em excesso torna a prosa burocrática.',
      x:['«Alugam-se quartos a estudantes.»', '«Precisa-se de cozinheiros.»'],
      s:['Voz ativa e voz passiva', 'Concordância verbal: casos difíceis'] },
    { n:'Artigo antes de nomes próprios e possessivos', a:'o João · a minha casa · a Inês',
      d:'No português europeu, o artigo definido usa-se normalmente antes de nomes de pessoas conhecidas e antes dos possessivos: «O João chegou», «a minha casa». No Brasil, sobretudo em registo escrito, omite-se com frequência.',
      u:'Na voz de um narrador próximo, familiar, use o artigo («a Inês», «o Tomás»); sem artigo, o nome soa mais distante, formal ou literário («Inês olhou o mar»). Antes de possessivos, o artigo é a regra em Portugal («o meu irmão»), exceto em vocativos («Meu filho, vem cá») e em algumas expressões («em minha casa», «por minha vontade»).',
      c:'Escolha um critério para o narrador e mantenha-o. A omissão sistemática do artigo («Encontrei meu irmão») soa a português do Brasil.',
      x:['Próximo: «A Inês desceu ao cais.»', 'Distante: «Inês desceu ao cais.»', '«Esta é a minha casa.» / «Meu Deus!»'],
      s:['Vocabulário de Portugal e do Brasil', 'Distância narrativa', 'Tratamento e concordância'] }
  ]);
})();
